def config_value(text: str, key: str) -> str:
    """Return the value bound to ``key`` in ``name=value`` config text.

    ``text`` is parsed line by line. Each line binds one name to one value,
    split on the first ``=``. Whitespace around the name and the value is
    ignored. If ``key`` does not appear, return an empty string. This
    function must not read files; all input comes from ``text``.
    """
    for line in text.splitlines():
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_config_value_returns_bound_value() -> None:
    assert config_value("host=example.com\nport=8080", "host") == "example.com"
    assert config_value("host=example.com\nport=8080", "port") == "8080"


def test_config_value_missing_key_returns_empty_string() -> None:
    assert config_value("host=example.com", "port") == ""


def test_config_value_empty_text_returns_empty_string() -> None:
    assert config_value("", "host") == ""


def test_config_value_strips_whitespace_around_name_and_value() -> None:
    assert config_value("  host  =  example.com  ", "host") == "example.com"


def test_config_value_splits_on_first_equals_sign() -> None:
    assert config_value("expr=a=b", "expr") == "a=b"


def test_config_value_does_not_match_partial_names() -> None:
    assert config_value("hostname=example.com", "host") == ""
